<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { Download, FileDown, FileUp, Landmark, Pencil, Plus } from 'lucide-vue-next'
import { api, apiError } from '../api/client'
import { fetchAllPages } from '../api/pagination'
import type { ApiResponse, Company, Receivable } from '../types'
import PageHeader from '../components/PageHeader.vue'
import ModalDialog from '../components/ModalDialog.vue'
import InlineAlert from '../components/InlineAlert.vue'

interface Account{id:string;company_id:string;bank_code:string;bank_name:string;branch:string;branch_digit?:string;account:string;account_digit?:string;account_type?:string;pix_key_type?:string;pix_key?:string;is_default:boolean;is_active?:boolean}
interface Agreement{id:string;company_id:string;bank_account_id:string;name:string;provider:string;environment:string;agreement_number?:string;wallet?:string;beneficiary_code?:string;cnab_layout:string;is_active:boolean}
const accounts=ref<Account[]>([]);const agreements=ref<Agreement[]>([]);const companies=ref<Company[]>([]);const receivables=ref<Receivable[]>([]);const returnCompanyId=ref('');const error=ref('');const success=ref('');const accountModal=ref(false);const agreementModal=ref(false);const cnabModal=ref(false);const editingAccount=ref<Account|null>(null);const editingAgreement=ref<Agreement|null>(null);const lastRemittance=ref<{id:string;sequence:number;layout:string}|null>(null);const downloading=ref(false)
const accountForm=reactive({company_id:'',bank_code:'001',bank_name:'Banco do Brasil',branch:'',branch_digit:'',account:'',account_digit:'',account_type:'CHECKING',pix_key_type:'',pix_key:'',is_default:true,is_active:true})
const agreementForm=reactive({company_id:'',bank_account_id:'',name:'Convênio de cobrança',provider:'SANDBOX',environment:'SANDBOX',agreement_number:'',wallet:'',beneficiary_code:'',cnab_layout:'240',is_active:true})
const cnabForm=reactive({bank_agreement_id:'',receivable_ids:[] as string[]})
const companyName=(id:string)=>companies.value.find(x=>x.id===id)?.trade_name||companies.value.find(x=>x.id===id)?.legal_name||'Empresa'
const money=(v:string)=>Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const providerLabel=(value:string)=>({SANDBOX:'Ambiente de testes',BANCO_DO_BRASIL:'Banco do Brasil',ITAU:'Itaú',SICOOB:'Sicoob',SICREDI:'Sicredi'}[value]||'Integração bancária')
const environmentLabel=(value:string)=>({SANDBOX:'Testes',HOMOLOGATION:'Homologação',PRODUCTION:'Produção'}[value]||value)
async function load(){error.value='';try{const [a,b,c,d]=await Promise.all([api.get<ApiResponse<Account[]>>('/v1/bank-accounts'),api.get<ApiResponse<Agreement[]>>('/v1/bank-agreements'),api.get<ApiResponse<Company[]>>('/v1/companies'),fetchAllPages<Receivable>('/v1/receivables')]);accounts.value=a.data.data;agreements.value=b.data.data;companies.value=c.data.data;receivables.value=d;if(!returnCompanyId.value&&companies.value[0])returnCompanyId.value=companies.value[0].id}catch(e){error.value=apiError(e)}}
function openAccount(item?:Account){editingAccount.value=item||null;Object.assign(accountForm,item?{company_id:item.company_id,bank_code:item.bank_code,bank_name:item.bank_name,branch:item.branch,branch_digit:item.branch_digit||'',account:item.account,account_digit:item.account_digit||'',account_type:item.account_type||'CHECKING',pix_key_type:item.pix_key_type||'',pix_key:item.pix_key||'',is_default:item.is_default,is_active:item.is_active??true}:{company_id:companies.value[0]?.id||'',bank_code:'001',bank_name:'Banco do Brasil',branch:'',branch_digit:'',account:'',account_digit:'',account_type:'CHECKING',pix_key_type:'',pix_key:'',is_default:true,is_active:true});accountModal.value=true}
async function saveAccount(){error.value='';try{if(editingAccount.value){await api.patch(`/v1/bank-accounts/${editingAccount.value.id}`,{bank_name:accountForm.bank_name,branch:accountForm.branch,branch_digit:accountForm.branch_digit||null,account:accountForm.account,account_digit:accountForm.account_digit||null,account_type:accountForm.account_type,pix_key_type:accountForm.pix_key_type||null,pix_key:accountForm.pix_key||null,is_default:accountForm.is_default,is_active:accountForm.is_active});success.value='Conta bancária atualizada.'}else{await api.post('/v1/bank-accounts',accountForm);success.value='Conta bancária cadastrada.'}accountModal.value=false;await load()}catch(e){error.value=apiError(e)}}
function openAgreement(item?:Agreement){editingAgreement.value=item||null;Object.assign(agreementForm,item?{company_id:item.company_id,bank_account_id:item.bank_account_id,name:item.name,provider:item.provider,environment:item.environment,agreement_number:item.agreement_number||'',wallet:item.wallet||'',beneficiary_code:item.beneficiary_code||'',cnab_layout:item.cnab_layout,is_active:item.is_active}:{company_id:companies.value[0]?.id||'',bank_account_id:'',name:'Convênio de cobrança',provider:'SANDBOX',environment:'SANDBOX',agreement_number:'',wallet:'',beneficiary_code:'',cnab_layout:'240',is_active:true});agreementModal.value=true}
async function saveAgreement(){error.value='';try{if(editingAgreement.value){await api.patch(`/v1/bank-agreements/${editingAgreement.value.id}`,{name:agreementForm.name,provider:agreementForm.provider,environment:agreementForm.environment,agreement_number:agreementForm.agreement_number||null,wallet:agreementForm.wallet||null,beneficiary_code:agreementForm.beneficiary_code||null,cnab_layout:agreementForm.cnab_layout,is_active:agreementForm.is_active});success.value='Convênio atualizado.'}else{await api.post('/v1/bank-agreements',{...agreementForm,settings:{},credentials:{}});success.value='Convênio cadastrado.'}agreementModal.value=false;await load()}catch(e){error.value=apiError(e)}}
async function downloadRemittance(){if(!lastRemittance.value)return;downloading.value=true;try{const item=lastRemittance.value;const response=await api.get(`/v1/cnab/remittances/${item.id}/download`,{responseType:'blob'});const href=URL.createObjectURL(response.data);const anchor=document.createElement('a');anchor.href=href;anchor.download=`REM-${String(item.sequence).padStart(6,'0')}-CNAB${item.layout}.REM`;document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(href)}catch(e){error.value=apiError(e)}finally{downloading.value=false}}
async function generateCnab(){error.value='';try{const r=await api.post<ApiResponse<{id:string;sequence:number}>>('/v1/cnab/remittances',cnabForm);const layout=agreements.value.find(x=>x.id===cnabForm.bank_agreement_id)?.cnab_layout||'240';lastRemittance.value={id:r.data.data.id,sequence:r.data.data.sequence,layout};success.value='Remessa CNAB gerada com sucesso. O arquivo está pronto para download.';cnabModal.value=false;await downloadRemittance()}catch(e){error.value=apiError(e)}}
async function importReturn(event:Event){const input=event.target as HTMLInputElement;if(!input.files?.[0])return;const data=new FormData();data.append('file',input.files[0]);error.value='';try{await api.post(`/v1/cnab/returns?company_id=${encodeURIComponent(returnCompanyId.value)}`,data,{headers:{'Content-Type':'multipart/form-data'}});success.value='Retorno bancário processado com sucesso.';await load()}catch(e){error.value=apiError(e)}finally{input.value=''}}
onMounted(load)
</script>
<template><PageHeader title="Bancos e CNAB" subtitle="Contas, convênios, remessas e retornos bancários."><select v-model="returnCompanyId" class="select max-w-64" aria-label="Empresa do retorno CNAB"><option v-for="c in companies" :key="c.id" :value="c.id">{{c.trade_name||c.legal_name}}</option></select><label class="btn-secondary cursor-pointer" :class="!returnCompanyId && 'pointer-events-none opacity-50'"><FileUp :size="18"/> Importar retorno<input type="file" class="hidden" accept=".ret,.txt" :disabled="!returnCompanyId" @change="importReturn"/></label><button class="btn-secondary" @click="cnabModal=true"><FileDown :size="18"/> Gerar remessa</button><button class="btn-secondary" @click="openAgreement()"><Plus :size="18"/> Convênio</button><button class="btn-primary" @click="openAccount()"><Plus :size="18"/> Conta bancária</button></PageHeader><InlineAlert :message="error" @dismiss="error=''"/><div v-if="success" class="mb-5 flex flex-wrap items-center gap-3 rounded-xl border border-emerald-100 bg-emerald-50 p-3 text-sm text-emerald-800"><span class="flex-1">{{success}}</span><button v-if="lastRemittance" class="btn-secondary" :disabled="downloading" @click="downloadRemittance"><Download :size="16"/>{{downloading?'Baixando…':'Baixar novamente'}}</button></div><div class="grid gap-6 lg:grid-cols-2"><section><h2 class="mb-3 text-lg font-semibold">Contas bancárias</h2><div class="space-y-3"><article v-for="item in accounts" :key="item.id" class="card flex items-center gap-3"><div class="rounded-xl bg-blue-50 p-3 text-blue-700"><Landmark :size="22"/></div><div class="min-w-0 flex-1"><p class="font-semibold">{{item.bank_code}} · {{item.bank_name}}</p><p class="text-sm text-slate-500">Ag. {{item.branch}} · Conta {{item.account}}-{{item.account_digit}}</p><p class="text-xs text-slate-400">{{companyName(item.company_id)}}</p></div><span v-if="item.is_default" class="badge bg-teal-100 text-teal-700">Padrão</span><button class="btn-secondary px-3 py-2" title="Editar conta" @click="openAccount(item)"><Pencil :size="15"/></button></article><p v-if="!accounts.length" class="card text-center text-slate-400">Nenhuma conta.</p></div></section><section><h2 class="mb-3 text-lg font-semibold">Convênios</h2><div class="space-y-3"><article v-for="item in agreements" :key="item.id" class="card"><div class="flex items-start gap-3"><div class="min-w-0 flex-1"><p class="font-semibold">{{item.name}}</p><p class="text-sm text-slate-500">{{providerLabel(item.provider)}} · {{environmentLabel(item.environment)}}</p><p class="mt-2 text-xs text-slate-400">Convênio {{item.agreement_number||'—'}} · Carteira {{item.wallet||'—'}} · CNAB {{item.cnab_layout}}</p></div><span class="badge" :class="item.is_active?'bg-emerald-100 text-emerald-700':'bg-slate-100 text-slate-500'">{{item.is_active?'Ativo':'Inativo'}}</span><button class="btn-secondary px-3 py-2" title="Editar convênio" @click="openAgreement(item)"><Pencil :size="15"/></button></div></article><p v-if="!agreements.length" class="card text-center text-slate-400">Nenhum convênio.</p></div></section></div>
<ModalDialog :open="accountModal" :title="editingAccount?'Editar conta bancária':'Cadastrar conta bancária'" size="lg" @close="accountModal=false"><form class="grid gap-4 md:grid-cols-2" @submit.prevent="saveAccount"><div class="md:col-span-2"><label class="label">Empresa</label><select v-model="accountForm.company_id" class="select" :disabled="!!editingAccount"><option v-for="c in companies" :key="c.id" :value="c.id">{{c.trade_name||c.legal_name}}</option></select></div><div><label class="label">Código banco</label><input v-model="accountForm.bank_code" maxlength="3" class="input" :disabled="!!editingAccount" required/></div><div><label class="label">Nome banco</label><input v-model="accountForm.bank_name" class="input" required/></div><div><label class="label">Agência</label><input v-model="accountForm.branch" class="input" required/></div><div><label class="label">Dígito agência</label><input v-model="accountForm.branch_digit" class="input"/></div><div><label class="label">Conta</label><input v-model="accountForm.account" class="input" required/></div><div><label class="label">Dígito conta</label><input v-model="accountForm.account_digit" class="input"/></div><div><label class="label">Tipo chave Pix</label><select v-model="accountForm.pix_key_type" class="select"><option value="">Sem chave</option><option value="CNPJ">CNPJ</option><option value="EMAIL">E-mail</option><option value="PHONE">Telefone</option><option value="EVP">Chave aleatória</option></select></div><div><label class="label">Chave Pix</label><input v-model="accountForm.pix_key" class="input"/></div><label class="flex gap-2 text-sm"><input v-model="accountForm.is_default" type="checkbox"/> Conta padrão da empresa</label><label v-if="editingAccount" class="flex gap-2 text-sm"><input v-model="accountForm.is_active" type="checkbox"/> Conta ativa</label><div class="md:col-span-2 flex justify-end gap-2"><button type="button" class="btn-secondary" @click="accountModal=false">Cancelar</button><button class="btn-primary">Salvar</button></div></form></ModalDialog>
<ModalDialog :open="agreementModal" :title="editingAgreement?'Editar convênio bancário':'Cadastrar convênio bancário'" size="lg" @close="agreementModal=false"><form class="grid gap-4 md:grid-cols-2" @submit.prevent="saveAgreement"><div><label class="label">Empresa</label><select v-model="agreementForm.company_id" class="select" :disabled="!!editingAgreement"><option v-for="c in companies" :key="c.id" :value="c.id">{{c.trade_name||c.legal_name}}</option></select></div><div><label class="label">Conta</label><select v-model="agreementForm.bank_account_id" class="select" :disabled="!!editingAgreement" required><option value="" disabled>Selecione</option><option v-for="a in accounts.filter(x=>x.company_id===agreementForm.company_id)" :key="a.id" :value="a.id">{{a.bank_name}} · {{a.account}}</option></select></div><div><label class="label">Nome</label><input v-model="agreementForm.name" class="input" required/></div><div><label class="label">Instituição / integração</label><select v-model="agreementForm.provider" class="select"><option value="SANDBOX">Ambiente de testes</option><option value="BANCO_DO_BRASIL">Banco do Brasil</option><option value="ITAU">Itaú</option><option value="SICOOB">Sicoob</option><option value="SICREDI">Sicredi</option></select></div><div><label class="label">Ambiente</label><select v-model="agreementForm.environment" class="select"><option value="SANDBOX">Testes</option><option value="HOMOLOGATION">Homologação</option><option value="PRODUCTION">Produção</option></select></div><div><label class="label">Layout</label><select v-model="agreementForm.cnab_layout" class="select"><option>240</option><option>400</option></select></div><div><label class="label">Número convênio</label><input v-model="agreementForm.agreement_number" class="input"/></div><div><label class="label">Carteira</label><input v-model="agreementForm.wallet" class="input"/></div><div><label class="label">Código beneficiário</label><input v-model="agreementForm.beneficiary_code" class="input"/></div><label v-if="editingAgreement" class="flex items-center gap-2 text-sm"><input v-model="agreementForm.is_active" type="checkbox"/> Convênio ativo</label><div class="md:col-span-2 rounded-xl bg-sky-50 p-3 text-xs text-sky-800">As credenciais de produção são protegidas pela plataforma e não ficam expostas nesta tela.</div><div class="md:col-span-2 flex justify-end gap-2"><button type="button" class="btn-secondary" @click="agreementModal=false">Cancelar</button><button class="btn-primary">Salvar</button></div></form></ModalDialog>
<ModalDialog :open="cnabModal" title="Gerar remessa CNAB" size="lg" @close="cnabModal=false"><form class="space-y-4" @submit.prevent="generateCnab"><div><label class="label">Convênio</label><select v-model="cnabForm.bank_agreement_id" class="select" required><option value="" disabled>Selecione</option><option v-for="a in agreements.filter(x=>x.is_active)" :key="a.id" :value="a.id">{{a.name}} · CNAB {{a.cnab_layout}}</option></select></div><div><label class="label">Títulos</label><div class="scroll-clean max-h-64 space-y-2 overflow-auto rounded-xl border border-slate-200 p-3"><label v-for="r in receivables.filter(x=>['OPEN','REGISTERED'].includes(x.status)&&x.company_id===agreements.find(a=>a.id===cnabForm.bank_agreement_id)?.company_id)" :key="r.id" class="flex items-center gap-3 rounded-lg p-2 hover:bg-slate-50"><input v-model="cnabForm.receivable_ids" type="checkbox" :value="r.id"/><span class="flex-1 text-sm">{{r.document_number}}</span><span class="text-sm font-semibold">{{money(r.balance)}}</span></label></div></div><div class="flex justify-end gap-2"><button type="button" class="btn-secondary" @click="cnabModal=false">Cancelar</button><button class="btn-primary" :disabled="!cnabForm.receivable_ids.length">Gerar e baixar</button></div></form></ModalDialog></template>
